    [Xunit.Fact]
    public static void TestAnFxIsTwoCells() {
        emon.Port.Cells c = emon.Port.NewCells();
        long big = (long) 98765432109;
        long neg = (long) -98765432109;
        emon.Testport.AssertEq(Fx.FxPush(c, big), 0, "first at 0");
        emon.Testport.AssertEq(Fx.FxPush(c, neg), 2, "second at 2");
        emon.Testport.AssertEq(emon.Port.CellsLen(c), 4, "four cells");
        emon.Testport.AssertThat(Fx.FxGet(c, 0) == big, "a positive value above 2^32 survives");
        emon.Testport.AssertThat(Fx.FxGet(c, 2) == neg, "and a negative one");
        Fx.FxPut(c, 0, (long) -1);
        emon.Testport.AssertThat(Fx.FxGet(c, 0) == ((long) -1), "minus one (all ones in the low half)");
        Fx.FxPut(c, 0, (long) 2147483648);
        emon.Testport.AssertThat(Fx.FxGet(c, 0) == ((long) 2147483648), "2^31: the low half's sign bit is not a sign");
        emon.Testport.AssertThat(Fx.FxJoin(0, -1) == ((long) 4294967295), "join reads the low half unsigned");
    }
    [Xunit.Fact]
    public static void TestMatricesComposeInPdfOrder() {
        emon.Port.Cells c = emon.Port.NewCells();
        int i = 0;
        while (i < 48) {
            Fx.FxPush(c, (long) 0);
            i += 2;
        }
        // 0: translate (10, 20); 12: scale 2 by 3; 24: result
        Fx.MxTranslate(c, 0, Fx.FxOfInt(10), Fx.FxOfInt(20));
        Fx.MxSet(c, 12, Fx.FxOfInt(2), (long) 0, (long) 0, Fx.FxOfInt(3), (long) 0, (long) 0);
        // translate then scale: (1,1) -> (11,21) -> (22,63)
        Fx.MxMul(c, 24, 0, 12);
        emon.Testport.AssertEq(Fx.FxRound(Fx.MxX(c, 24, Fx.FxOfInt(1), Fx.FxOfInt(1))), 22, "x");
        emon.Testport.AssertEq(Fx.FxRound(Fx.MxY(c, 24, Fx.FxOfInt(1), Fx.FxOfInt(1))), 63, "y");
        // scale then translate: (1,1) -> (2,3) -> (12,23)
        Fx.MxMul(c, 24, 12, 0);
        emon.Testport.AssertEq(Fx.FxRound(Fx.MxX(c, 24, Fx.FxOfInt(1), Fx.FxOfInt(1))), 12, "x, other order");
        emon.Testport.AssertEq(Fx.FxRound(Fx.MxY(c, 24, Fx.FxOfInt(1), Fx.FxOfInt(1))), 23, "y, other order");
        // a product written over an operand
        Fx.MxMul(c, 12, 12, 0);
        emon.Testport.AssertEq(Fx.FxRound(Fx.MxX(c, 12, Fx.FxOfInt(1), Fx.FxOfInt(1))), 12, "dst is x");
        Fx.MxIdent(c, 36);
        Fx.MxMul(c, 36, 36, 36);
        emon.Testport.AssertEq(Fx.FxRound(Fx.MxX(c, 36, Fx.FxOfInt(7), Fx.FxOfInt(9))), 7, "the identity squared");
        emon.Testport.AssertEq(Fx.FxRound(Fx.MxY(c, 36, Fx.FxOfInt(7), Fx.FxOfInt(9))), 9, "is the identity");
    }
    [Xunit.Fact]
    public static void TestARotationBy90TurnsTheAxes() {
        emon.Port.Cells c = emon.Port.NewCells();
        int i = 0;
        while (i < 24) {
            Fx.FxPush(c, (long) 0);
            i += 2;
        }
        // [0 1 -1 0 0 0]: x axis to y, y axis to -x
        Fx.MxSet(c, 0, (long) 0, Fx.FxOfInt(1), Fx.FxOfInt(-1), (long) 0, (long) 0, (long) 0);
        emon.Testport.AssertEq(Fx.FxRound(Fx.MxX(c, 0, Fx.FxOfInt(1), (long) 0)), 0, "(1,0) x");
        emon.Testport.AssertEq(Fx.FxRound(Fx.MxY(c, 0, Fx.FxOfInt(1), (long) 0)), 1, "(1,0) y");
        emon.Testport.AssertEq(Fx.FxRound(Fx.MxX(c, 0, (long) 0, Fx.FxOfInt(1))), -1, "(0,1) x");
        Fx.MxCopy(c, 12, 0);
        Fx.MxMul(c, 12, 12, 0);
        emon.Testport.AssertEq(Fx.FxRound(Fx.MxX(c, 12, Fx.FxOfInt(1), (long) 0)), -1, "twice is 180 degrees");
    }
    internal static int FxtDist(long v, int want) {
        // |v - want| in raw Fx units.
        int d = ((int) v) - want;
        if (d < 0) {
            return 0 - d;
        }
        return d;
    }
    [Xunit.Fact]
    public static void TestSineAndCosineAreExactAtTheAxesAndCloseBetween() {
        emon.Testport.AssertEq(FxtRaw(Fx.FxCos(0)), 16777216, "cos 0");
        emon.Testport.AssertEq(FxtRaw(Fx.FxSin(0)), 0, "sin 0");
        emon.Testport.AssertEq(FxtRaw(Fx.FxCos(9000)), 0, "cos 90");
        emon.Testport.AssertEq(FxtRaw(Fx.FxSin(9000)), 16777216, "sin 90");
        emon.Testport.AssertEq(FxtRaw(Fx.FxCos(18000)), -16777216, "cos 180");
        emon.Testport.AssertEq(FxtRaw(Fx.FxSin(18000)), 0, "sin 180");
        emon.Testport.AssertEq(FxtRaw(Fx.FxCos(27000)), 0, "cos 270");
        emon.Testport.AssertEq(FxtRaw(Fx.FxSin(27000)), -16777216, "sin 270");
        emon.Testport.AssertThat(FxtDist(Fx.FxSin(4500), 11863283) <= 700, "sin 45 = 0.70711");
        emon.Testport.AssertThat(FxtDist(Fx.FxCos(4500), 11863283) <= 700, "cos 45");
        emon.Testport.AssertThat(FxtDist(Fx.FxSin(3000), 8388608) <= 700, "sin 30 = 0.5");
        emon.Testport.AssertThat(FxtDist(Fx.FxCos(6000), 8388608) <= 700, "cos 60 = 0.5");
        emon.Testport.AssertThat(FxtDist(Fx.FxCos(13500), -11863283) <= 700, "cos 135");
        emon.Testport.AssertThat(FxtDist(Fx.FxSin(31500), -11863283) <= 700, "sin 315");
        emon.Testport.AssertThat(FxtDist(Fx.FxSin(-4500), -11863283) <= 700, "a negative angle");
        emon.Testport.AssertThat(FxtDist(Fx.FxCos(40500), 11863283) <= 700, "an angle past a turn");
    }
